import Foundation
#if canImport(FoundationNetworking)
import FoundationNetworking
#endif

// Stdio <-> HTTP Bridge for PDF Content Search MCP server.
// Reads JSON-RPC from stdin, forwards each message to the app's HTTP endpoint
// at http://127.0.0.1:<PORT>/mcp with a Bearer token, writes responses to stdout.
//
// Env vars:
//   PDF_CS_TOKEN : Bearer token matching the app's API server token
//   PDF_CS_PORT  : port (default 44477)
//   PDF_CS_HOST  : host (default 127.0.0.1)
//
// When the app is unreachable (e.g. an offline introspection/registry
// container), "initialize" and "tools/list" are answered from a baked-in
// static snapshot so MCP directories can still discover the tool surface.
// All other methods, and live "tools/list" when the app IS reachable, are
// proxied to the app verbatim.

// Static fallbacks (base64-encoded JSON), used only when the app is unreachable.
let STATIC_INIT_B64 = "eyJwcm90b2NvbFZlcnNpb24iOiIyMDI1LTAzLTI2IiwiY2FwYWJpbGl0aWVzIjp7InRvb2xzIjp7Imxpc3RDaGFuZ2VkIjp0cnVlfX0sInNlcnZlckluZm8iOnsibmFtZSI6IlBERiBDb250ZW50IFNlYXJjaCIsInZlcnNpb24iOiIxLjIwLjAifX0="
let STATIC_TOOLS_B64 = ""

struct Config {
    let host: String
    let port: Int
    let token: String

    static func fromEnvironment() -> Config {
        let env = ProcessInfo.processInfo.environment
        let token = env["PDF_CS_TOKEN"] ?? ""
        let host = env["PDF_CS_HOST"] ?? "127.0.0.1"
        let port = Int(env["PDF_CS_PORT"] ?? "44477") ?? 44477
        return Config(host: host, port: port, token: token)
    }

    var endpoint: URL? { URL(string: "http://\(host):\(port)/mcp") }
}

final class Bridge {
    private let config: Config
    private let session: URLSession
    private var sessionId: String?
    private let stdout = FileHandle.standardOutput

    init(config: Config) {
        self.config = config
        let c = URLSessionConfiguration.default
        c.timeoutIntervalForRequest = 30
        c.timeoutIntervalForResource = 60
        self.session = URLSession(configuration: c)
    }

    func run() {
        let input = FileHandle.standardInput
        var buffer = Data()
        while true {
            let chunk = input.availableData
            if chunk.isEmpty { return }
            buffer.append(chunk)
            while let newlineIdx = buffer.firstIndex(of: 0x0A) {
                let line = buffer.subdata(in: 0..<newlineIdx)
                buffer.removeSubrange(0...newlineIdx)
                if line.isEmpty { continue }
                handle(line: line)
            }
        }
    }

    private func handle(line: Data) {
        let (extractedId, method) = parse(line)

        guard let url = config.endpoint else {
            emitError(id: extractedId, code: -32603, message: "Internal bridge error: invalid endpoint URL")
            return
        }

        var request = URLRequest(url: url)
        request.httpMethod = "POST"
        request.setValue("application/json", forHTTPHeaderField: "Content-Type")
        if !config.token.isEmpty {
            request.setValue("Bearer \(config.token)", forHTTPHeaderField: "Authorization")
        }
        if let sid = sessionId { request.setValue(sid, forHTTPHeaderField: "Mcp-Session-Id") }
        request.httpBody = line

        let semaphore = DispatchSemaphore(value: 0)
        var responseData: Data?
        var httpResponse: HTTPURLResponse?
        var transportError: Error?

        let task = session.dataTask(with: request) { data, response, error in
            responseData = data
            httpResponse = response as? HTTPURLResponse
            transportError = error
            semaphore.signal()
        }
        task.resume()
        semaphore.wait()

        if transportError != nil {
            // App unreachable: serve static snapshot for discovery methods.
            if method == "initialize" { emitStatic(id: extractedId, resultB64: STATIC_INIT_B64); return }
            if method == "tools/list" { emitStatic(id: extractedId, resultB64: STATIC_TOOLS_B64); return }
            emitError(id: extractedId, code: -32000,
                      message: "Cannot reach PDF Content Search: \(transportError!.localizedDescription). Is the app running and API server enabled?")
            return
        }

        guard let resp = httpResponse else {
            emitError(id: extractedId, code: -32603, message: "No HTTP response")
            return
        }
        if let sid = resp.value(forHTTPHeaderField: "Mcp-Session-Id"), !sid.isEmpty { sessionId = sid }
        if resp.statusCode == 202 { return }
        if resp.statusCode == 401 {
            emitError(id: extractedId, code: -32001,
                      message: "Authentication failed: invalid API token. Re-run the Claude Desktop setup in PDF Content Search preferences.")
            return
        }
        if resp.statusCode == 404, let sid = sessionId {
            sessionId = nil
            emitError(id: extractedId, code: -32001,
                      message: "MCP session expired (was: \(sid)). Client should send 'initialize' again.")
            return
        }
        guard let data = responseData, !data.isEmpty else {
            if resp.statusCode >= 400 {
                emitError(id: extractedId, code: -32603, message: "HTTP \(resp.statusCode) with empty body")
            }
            return
        }
        var out = data
        out.append(0x0A)
        stdout.write(out)
    }

    private func parse(_ data: Data) -> (Any?, String) {
        guard let obj = try? JSONSerialization.jsonObject(with: data) else { return (nil, "") }
        if let dict = obj as? [String: Any] {
            return (dict["id"], dict["method"] as? String ?? "")
        }
        if let arr = obj as? [Any], let first = arr.first as? [String: Any] {
            return (first["id"], first["method"] as? String ?? "")
        }
        return (nil, "")
    }

    private func emitStatic(id: Any?, resultB64: String) {
        guard let data = Data(base64Encoded: resultB64),
              let result = try? JSONSerialization.jsonObject(with: data) else {
            emitError(id: id, code: -32603, message: "Static snapshot decode failed")
            return
        }
        var response: [String: Any] = ["jsonrpc": "2.0", "result": result]
        response["id"] = id ?? NSNull()
        guard let out = try? JSONSerialization.data(withJSONObject: response) else { return }
        var o = out; o.append(0x0A); stdout.write(o)
    }

    private func emitError(id: Any?, code: Int, message: String) {
        var response: [String: Any] = ["jsonrpc": "2.0", "error": ["code": code, "message": message]]
        response["id"] = id ?? NSNull()
        guard let data = try? JSONSerialization.data(withJSONObject: response) else { return }
        var out = data; out.append(0x0A); stdout.write(out)
    }
}

Bridge(config: Config.fromEnvironment()).run()
